head.script:
// jQuery 조회 순서(받은 선택자 → 없으면 mf_ 접두사). 2026-11
scwin.__getJq = function(q) {
	var j = $(q); if (j.length) return j;
	var P = 'mf_', t = q.trim(), r = t.slice(1);
	if (r.slice(0, 2) === 'G_') r = 'G_' + P + r.slice(2); else if (r.slice(0, P.length) !== P) r = P + r;
	return $(t.slice(0, 1) + r);
};
scwin.onpageload = function() {
	var totRow = 100;
	var totCol = grid1.getTotalCol();
	var arr = [];
	for (var i = 0; i < totRow; i++) {
		for (var j = 0; j < totCol; j++) {
			arr.push("index_" + i + "_" + j);
		}
	}
	grid1.setData(arr);
};
scwin.trigger1_onclick = function(e) {
	grid1.setRowBackgroundColor(50, "yellow");
	for (var i = 10; i < 50; i++) {
		grid1.setRowBackgroundColor(i, "yellow");
		grid1.setRowVisible(i, false);
	}
};
scwin.checkColor = function(id, value, rgb) {
	var color = scwin.__getJq(id).css("background-color");
	if (color.indexOf("rgb") != -1) {
		return color == rgb;
	}
	return color == value;
}
scwin.setVal1 = function() {
	((j) => j.length ? j : $('#mf_grid1_scrollY_div'))($('#grid1_scrollY_div')).animate ({scrollTop:360}, 50);
}
scwin.setVal2 = function() {
	((j) => j.length ? j : $('#mf_grid1_scrollY_div'))($('#grid1_scrollY_div')).animate ({scrollTop:50}, 50);
}
scwin.checkVal = function() {
	return scwin.__getJq(((j) => j.length ? j : $('#mf_grid1_body_tbody tr'))($('#grid1_body_tbody tr'))[38]).css('display') == 'none' && scwin.__getJq(((j) => j.length ? j : $('#mf_grid1_body_tbody tr'))($('#grid1_body_tbody tr'))[38]).is(':visible') == false;
}
